def calculate_simple_interest_C6(
    ws_account_balance: Decimal,
    ws_interest_rate: Decimal,
    ws_days_in_period: int
) -> Decimal:
    """
    Calculates simple interest based on account balance, interest rate, and days
    This function calculates simple interest using the formula:
    ws_simple_interest = ws_account_balance * ws_interest_rate * ws_days_in_period / 36500

    Args:
        ws_account_balance: The account balance
        ws_interest_rate: The interest rate
        ws_days_in_period: The number of days in the period
    Returns:
        Decimal: The calculated simple interest
    Raises:
        ValueError: If any of the inputs are invalid types
        ZeroDivisionError: If ws_days_in_period is 0 (to prevent division by zero)
    Example:
        >>> calculate_simple_interest(Decimal('1000'), Decimal('0.05'), 365)
        Decimal('0.50')
    """
    logger.info("Calculating simple interest.")

    # Validate inputs
    if not isinstance(ws_account_balance, Decimal):
        logger.error(f"Invalid input type for ws_account_balance: {type(ws_account_balance)}")
        raise ValueError("ws_account_balance must be a Decimal.")
    if not isinstance(ws_interest_rate, Decimal):
        logger.error(f"Invalid input type for ws_interest_rate: {type(ws_interest_rate)}")
        raise ValueError("ws_interest_rate must be a Decimal.")
    if not isinstance(ws_days_in_period, int):
        logger.error(f"Invalid input type for ws_days_in_period: {type(ws_days_in_period)}")
        raise ValueError("ws_days_in_period must be an integer.")
    if ws_days_in_period == 0:
        logger.error("ws_days_in_period cannot be zero.")
        raise ZeroDivisionError("ws_days_in_period cannot be zero.")

    try:
        # COMPUTE ws_simple_interest = ws_account_balance * ws_interest_rate * ws_days_in_period / 36500
        ws_simple_interest = ws_account_balance * ws_interest_rate * Decimal(str(ws_days_in_period)) / Decimal('36500')
        logger.debug(f"Calculated simple interest: {ws_simple_interest}")
        return ws_simple_interest

    except Exception as e:
        logger.error(f"Error calculating simple interest: {e}")
        raise

def calculate_compound_interest_C6(
    ws_account_balance: Decimal,
    ws_interest_rate: Decimal,
    ws_days_in_period: int
) -> Decimal:
    """
    Calculates compound interest based on account balance, interest rate, and days
    This function calculates compound interest using the formulas:
    ws_compound_factor = (1 + ws_interest_rate / 36500) ** ws_days_in_period
    ws_compound_interest = ws_account_balance * (ws_compound_factor - 1)

    Args:
        ws_account_balance: The account balance
        ws_interest_rate: The interest rate
        ws_days_in_period: The number of days in the period
    Returns:
        Decimal: The calculated compound interest
    Raises:
        ValueError: If any of the inputs are invalid types
        ZeroDivisionError: If 36500 would result in division by zero (though highly unlikely)
    Example:
        >>> calculate_compound_interest(Decimal('1000'), Decimal('0.05'), 365)
        Decimal('51.27')
    """
    logger.info("Calculating compound interest.")

    # Validate inputs
    if not isinstance(ws_account_balance, Decimal):
        logger.error(f"Invalid input type for ws_account_balance: {type(ws_account_balance)}")
        raise ValueError("ws_account_balance must be a Decimal.")
    if not isinstance(ws_interest_rate, Decimal):
        logger.error(f"Invalid input type for ws_interest_rate: {type(ws_interest_rate)}")
        raise ValueError("ws_interest_rate must be a Decimal.")
    if not isinstance(ws_days_in_period, int):
        logger.error(f"Invalid input type for ws_days_in_period: {type(ws_days_in_period)}")
        raise ValueError("ws_days_in_period must be an integer.")

    try:
        # COMPUTE ws_compound_factor = (1 + ws_interest_rate / 36500) ** ws_days_in_period
        ws_compound_factor = (Decimal('1') + ws_interest_rate / Decimal('36500')) ** ws_days_in_period
        logger.debug(f"Calculated compound factor: {ws_compound_factor}")

        # COMPUTE ws_compound_interest = ws_account_balance * (ws_compound_factor - 1)
        ws_compound_interest = ws_account_balance * (ws_compound_factor - Decimal('1'))
        logger.debug(f"Calculated compound interest: {ws_compound_interest}")

        return ws_compound_interest

    except Exception as e:
        logger.error(f"Error calculating compound interest: {e}")
        raise

def apply_interest_C6(
    ws_interest_method: str,
    ws_simple_interest: Decimal,
    ws_compound_interest: Decimal,
    ws_account_balance: Decimal,
    perform_2350_update_account: callable  # Type hint for a function, adjust if needed
) -> Decimal:
    """
    Applies either simple or compound interest to the account balance
    This function checks the ws_interest_method. If it's 'S', it adds'
    the simple interest to the account balance. Otherwise (presumably 'C' for compound),
    it adds the compound interest. Then it calls the 2350-update_account procedure
    Args:
        ws_interest_method: A string indicating the interest method ('S' for simple)
        ws_simple_interest: The calculated simple interest amount
        ws_compound_interest: The calculated compound interest amount
        ws_account_balance: The current account balance. This value will be modified
        perform_2350_update_account: A callable (function) representing the 2350-update_account paragraph/function
    Returns:
        Decimal: The updated account balance
    Raises:
        ValueError: If ws_interest_method is not a string or is an invalid value
        ValueError: If ws_simple_interest or ws_compound_interest is not a Decimal
        TypeError: If perform_2350_update_account is not callable
    Example:
        >>> 
def fake_update_account(): pass
        >>> apply_interest('S', Decimal('10.00'), Decimal('12.00'), Decimal('1000.00'), fake_update_account)
        Decimal('1010.00')
    """
    logger.info("Applying interest to account balance.")

    # Validate inputs
    if not isinstance(ws_interest_method, str):
        logger.error(f"Invalid input type for ws_interest_method: {type(ws_interest_method)}")
        raise ValueError("ws_interest_method must be a string.")

    if ws_interest_method not in ('S', 'C'): # Expanded for clarity, could have more methods
        logger.error(f"Invalid value for ws_interest_method: {ws_interest_method}")
        raise ValueError("ws_interest_method must be 'S' or 'C'.")

    if not isinstance(ws_simple_interest, Decimal):
        logger.error(f"Invalid input type for ws_simple_interest: {type(ws_simple_interest)}")
        raise ValueError("ws_simple_interest must be a Decimal.")
    if not isinstance(ws_compound_interest, Decimal):
        logger.error(f"Invalid input type for ws_compound_interest: {type(ws_compound_interest)}")
        raise ValueError("ws_compound_interest must be a Decimal.")
    if not callable(perform_2350_update_account):
        logger.error(f"Invalid input type for perform_2350_update_account: {type(perform_2350_update_account)}")
        raise TypeError("perform_2350_update_account must be a callable (function).")

    try:
        # IF ws_interest_method = 'S'
        if ws_interest_method == 'S':
            # ADD ws_simple_interest TO ws_account_balance
            ws_account_balance += ws_simple_interest
            logger.debug(f"Added simple interest. New balance: {ws_account_balance}")
        else:
            # ADD ws_compound_interest TO ws_account_balance
            ws_account_balance += ws_compound_interest
            logger.debug(f"Added compound interest. New balance: {ws_account_balance}")

        # PERFORM 2350-update_account
        perform_2350_update_account()
        logger.debug("Performed 2350-update_account.")

        return ws_account_balance

    except Exception as e:
        logger.error(f"Error applying interest: {e}")
        raise

def fee_processing_C6(
    perform_8100_calculate_monthly_fee: callable,
    perform_8200_calculate_transaction_fees: callable,
    perform_8300_apply_fee_waivers: callable,
    perform_8400_deduct_fees: callable,
) -> None:
    """
    Processes fees by performing a series of calculations and applying waivers
    This function orchestrates the fee processing steps by calling:
    - 8100-calculate_monthly_fee to determine the monthly fee
    - 8200-calculate_transaction_fees to calculate transaction fees
    - 8300-apply_fee_waivers to apply any eligible fee waivers
    - 8400-deduct_fees to deduct the calculated fees from the account
    Args:
        perform_8100_calculate_monthly_fee: Function to calculate the monthly fee
        perform_8200_calculate_transaction_fees: Function to calculate transaction fees
        perform_8300_apply_fee_waivers: Function to apply fee waivers
        perform_8400_deduct_fees: Function to deduct the total fees
    Returns:
        None

    Raises:
        TypeError: If any of the input arguments are not callable
    """
    logger.info("Performing fee processing.")

    # Validate inputs
