def record_fee_transaction_C6(
    txn_account_id: str,
    ws_total_fees: Decimal,
    fee_description: str,
    write_fee_record: callable,
    ws_fee_record: WsFeeRecord
) -> None:
    """
    Records a fee transaction
    This function initializes a fee record, populates it with data, and writes it to a file
    It moves the transaction account ID to the fee account, total fees to the fee amount,
    a description to the fee description, and the current date to the fee date
    Finally, it writes the fee record
    Args:
        txn_account_id: The transaction account ID
        ws_total_fees: The total fees amount
        fee_description: Description of the fee
        write_fee_record: A callable(ws_fee_record: WsFeeRecord) for file output, replacing 'WRITE fee_record FROM ws_fee_record'
        ws_fee_record: Data
class to hold fee record info

    Returns:
        None

    Raises:
        ValueError: If any of the inputs are invalid types
        TypeError: If write_fee_record is not callable
    """
    logger.info("Recording fee transaction.")

    # Validate inputs
    if not isinstance(txn_account_id, str):
        logger.error(f"Invalid input type for txn_account_id: {type(txn_account_id)}")
        raise ValueError("txn_account_id must be a string.")
    if not isinstance(ws_total_fees, Decimal):
        logger.error(f"Invalid input type for ws_total_fees: {type(ws_total_fees)}")
        raise ValueError("ws_total_fees must be a Decimal.")
    if not isinstance(fee_description, str):
        logger.error(f"Invalid input type for fee_description: {type(fee_description)}")
        raise ValueError("fee_description must be a string.")
    if not callable(write_fee_record):
        logger.error(f"Invalid input type for write_fee_record: {type(write_fee_record)}")
        raise TypeError("write_fee_record must be a callable (function).")

    try:
        # INITIALIZE ws_fee_record
        # In the original COBOL, INITIALIZE zeroes the struct. Because this function
        # receives a new object (rather than a commarea), this effect has already
        # been accomplished. No extra initializion needed!

        # MOVE txn_account_id TO fee_account
        ws_fee_record.fee_account = txn_account_id
        logger.debug(f"Fee account set to: {txn_account_id}")

        # MOVE ws_total_fees TO fee_amount
        ws_fee_record.fee_amount = ws_total_fees
        logger.debug(f"Fee amount set to: {ws_total_fees}")

        # MOVE 'MONTHLY FEE' TO fee_description
        ws_fee_record.fee_description = fee_description # was "MONTHLY FEE" - made param for reuse
        logger.debug(f"Fee description set to: {fee_description}")

        # MOVE FUNCTION current_date TO fee_date
        ws_fee_record.fee_date = date.today()
        logger.debug(f"Fee date set to: {ws_fee_record.fee_date}")

        # WRITE fee_record FROM ws_fee_record
        write_fee_record(ws_fee_record)
        logger.debug("Wrote fee record.")

    except Exception as e:
        logger.error(f"Error recording fee transaction: {e}")
        raise

