# Initialize logger
logger = logging.getLogger(__name__)

def evaluate_premium_C8(
    ws_marital_status: int,
    ws_base_premium: Decimal,
    ws_driver_age: int,
    ws_accidents_3yr: int,
    ws_violations_3yr: int,
    ws_annual_premium: Decimal,
    ws_monthly_premium: Decimal
) -> tuple[Decimal, Decimal]:
    """
    Calculates the annual and monthly premium based on various risk factors
    This function adjusts the base premium based on driver age, accident history,
    and violations, then calculates the annual and monthly premiums
    Args:
        ws_marital_status (int): The driver's marital status. Values are 1-single, 2-married.'
        ws_base_premium (Decimal): The initial base premium
        ws_driver_age (int): The driver's age.'
        ws_accidents_3yr (int): The number of accidents in the last 3 years
        ws_violations_3yr (int): The number of violations in the last 3 years
        ws_annual_premium (Decimal): The driver's annual premium.'
        ws_monthly_premium (Decimal): The driver's monthly premium.'

    Returns:
        tuple[Decimal, Decimal]: A tuple containing the updated annual and monthly premium
    Raises:
        ValueError: If any of the input values are invalid
    Example:
        >>> evaluate_premium_C8(1, Decimal('500'), 22, 1, 2, Decimal('0'), Decimal('0'))
        (Decimal('900.00'), Decimal('75.00'))
    """
    logger.info("Starting evaluate_premium_C8")

    # Input validation
    if not isinstance(ws_marital_status, int) or ws_marital_status not in (1, 2):
        logger.error(f"Invalid marital status: {ws_marital_status}")
        raise ValueError("Invalid marital status. Must be 1 (single) or 2 (married).")
    if not isinstance(ws_base_premium, Decimal):
        logger.error(f"Invalid base premium: {ws_base_premium}")
        raise ValueError("Base premium must be a Decimal.")
    if not isinstance(ws_driver_age, int):
        logger.error(f"Invalid driver age: {ws_driver_age}")
        raise ValueError("Driver age must be an integer.")
    if not isinstance(ws_accidents_3yr, int):
        logger.error(f"Invalid accidents count: {ws_accidents_3yr}")
        raise ValueError("Accidents count must be an integer.")
    if not isinstance(ws_violations_3yr, int):
        logger.error(f"Invalid violations count: {ws_violations_3yr}")
        raise ValueError("Violations count must be an integer.")

    try:
        # Evaluate marital status and adjust base premium
        if ws_marital_status in (6, 7, 8, 9, 10):
            ws_base_premium += Decimal('100')
            logger.debug("Marital status adjusted base premium by 100")
        else:
            ws_base_premium += Decimal('50')
            logger.debug("Marital status adjusted base premium by 50")

        # Adjust premium based on driver age
        if ws_driver_age < 25:
            ws_base_premium *= Decimal('1.5')
            logger.debug("Driver age adjusted base premium by 1.5")

        # Add accident surcharge if accidents exist
        if ws_accidents_3yr > 0:
            ws_accident_surcharge = Decimal(ws_accidents_3yr * 200)
            ws_base_premium += ws_accident_surcharge
            logger.debug(f"Added accident surcharge: {ws_accident_surcharge}")

        # Add violation surcharge if violations exist
        if ws_violations_3yr > 0:
            ws_violation_surcharge = Decimal(ws_violations_3yr * 100)
            ws_base_premium += ws_violation_surcharge
            logger.debug(f"Added violation surcharge: {ws_violation_surcharge}")

        # Move base premium to annual premium
        ws_annual_premium = ws_base_premium
        logger.debug(f"Annual premium set to: {ws_annual_premium}")

        # Calculate monthly premium
        ws_monthly_premium = ws_annual_premium / Decimal('12')
        ws_monthly_premium = ws_monthly_premium.quantize(Decimal('0.01')) # Quantize to 2 decimal places
        logger.debug(f"Monthly premium calculated as: {ws_monthly_premium}")

        logger.info("Completed evaluate_premium_C8 successfully")
        return ws_annual_premium.quantize(Decimal('0.01')), ws_monthly_premium

    except Exception as e:
        logger.error(f"Error in evaluate_premium_C8: {e}")
        raise

def calc_home_premium_C8(
    ws_coverage_amount: Decimal,
    ws_home_age: int,
    ws_flood_zone: str,
    ws_security_system: str,
    ws_deductible: Decimal,
    ws_base_premium: Decimal,
    ws_annual_premium: Decimal,
    ws_monthly_premium: Decimal
) -> tuple[Decimal, Decimal]:
    """
    Calculates home insurance premium based on coverage amount, home age, flood zone, and security system
    The function computes the base premium based on coverage amount, adjusts it based on home age,
    flood zone status, and security system presence. It also applies a deductible credit and ensures
    the base premium doesn't fall below a minimum value.'

    Args:
        ws_coverage_amount (Decimal): The coverage amount for the home
        ws_home_age (int): The age of the home in years
        ws_flood_zone (str): Indicates if the home is in a flood zone ('Y' or 'N')
        ws_security_system (str): Indicates if the home has a security system ('Y' or 'N')
        ws_deductible (Decimal): The deductible amount
        ws_base_premium (Decimal): The current base premium amount
        ws_annual_premium (Decimal): The current annual premium amount
        ws_monthly_premium (Decimal): The current monthly premium amount
    Returns:
        tuple[Decimal, Decimal]: A tuple containing the calculated annual premium and monthly premium
    Raises:
        ValueError: If any input values are invalid
    Example:
        >>> calc_home_premium_C8(Decimal('250000'), 15, 'N', 'Y', Decimal('1000'), Decimal('0'), Decimal('0'), Decimal('0'))
        (Decimal('625.00'), Decimal('52.08'))
    """
    logger.info("Starting calc_home_premium_C8")

    # Input validation
    if not isinstance(ws_coverage_amount, Decimal):
        logger.error(f"Invalid coverage amount: {ws_coverage_amount}")
        raise ValueError("Coverage amount must be a Decimal.")
    if not isinstance(ws_home_age, int):
        logger.error(f"Invalid home age: {ws_home_age}")
        raise ValueError("Home age must be an integer.")
    if not isinstance(ws_flood_zone, str) or ws_flood_zone not in ('Y', 'N'):
        logger.error(f"Invalid flood zone indicator: {ws_flood_zone}")
        raise ValueError("Flood zone must be 'Y' or 'N'.")
    if not isinstance(ws_security_system, str) or ws_security_system not in ('Y', 'N'):
        logger.error(f"Invalid security system indicator: {ws_security_system}")
        raise ValueError("Security system must be 'Y' or 'N'.")
    if not isinstance(ws_deductible, Decimal):
        logger.error(f"Invalid deductible amount: {ws_deductible}")
        raise ValueError("Deductible must be a Decimal.")

    try:
        # Compute base premium
        ws_base_premium = ws_coverage_amount * Decimal('0.003')
        logger.debug(f"Initial base premium: {ws_base_premium}")

        # Evaluate home age and adjust base premium
        if 0 <= ws_home_age <= 10:
            ws_base_premium *= Decimal('0.9')
            logger.debug("Home age adjusted base premium by 0.9")
        elif 11 <= ws_home_age <= 25:
            ws_base_premium *= Decimal('1.0')
            logger.debug("Home age adjusted base premium by 1.0")
        elif 26 <= ws_home_age <= 50:
            ws_base_premium *= Decimal('1.2')
            logger.debug("Home age adjusted base premium by 1.2")
        else:
            ws_base_premium *= Decimal('1.5')
            logger.debug("Home age adjusted base premium by 1.5")

        # Adjust premium for flood zone
        if ws_flood_zone == 'Y':
            ws_base_premium *= Decimal('1.5')
            logger.debug("Flood zone adjusted base premium by 1.5")

        # Adjust premium for security system
        if ws_security_system == 'Y':
            ws_base_premium *= Decimal('0.9')
            logger.debug("Security system adjusted base premium by 0.9")

        # Compute deductible credit
        ws_deductible_credit = ws_deductible / Decimal('1000') * Decimal('50')
        logger.debug(f"Deductible credit: {ws_deductible_credit}")

        # Subtract deductible credit from base premium
        ws_base_premium -= ws_deductible_credit
        logger.debug(f"Base premium after deductible credit: {ws_base_premium}")

        # Ensure base premium is not below 200
        if ws_base_premium < Decimal('200'):
            ws_base_premium = Decimal('200')
            logger.debug("Base premium set to minimum of 200")

        # Move base premium to annual premium
        ws_annual_premium = ws_base_premium
        logger.debug(f"Annual premium set to: {ws_annual_premium}")

        # Calculate monthly premium
        ws_monthly_premium = ws_annual_premium / Decimal('12')
        ws_monthly_premium = ws_monthly_premium.quantize(Decimal('0.01'))

        logger.info("Completed calc_home_premium_C8 successfully")
        return ws_annual_premium.quantize(Decimal('0.01')), ws_monthly_premium

    except Exception as e:
        logger.error(f"Error in calc_home_premium_C8: {e}")
        raise

def calc_health_premium_C8(
    ws_insured_age: int,
    ws_plan_type: str,
    ws_family_plan: str,
    ws_base_premium: Decimal,
    ws_monthly_premium: Decimal,
    ws_annual_premium: Decimal
) -> tuple[Decimal, Decimal]:
    """
    Calculates health insurance premium based on insured age, plan type, and family plan status
    This function starts with a base premium and adjusts it based on the insured's age,'
    the selected plan type (Bronze, Silver, Gold, Platinum), and whether it's a family plan.'

    Args:
        ws_insured_age (int): The age of the insured person
        ws_plan_type (str): The type of insurance plan (e.g., 'BRONZE', 'SILVER', 'GOLD', 'PLATINUM')
        ws_family_plan (str): Indicates if it's a family plan ('Y' or 'N').'
        ws_base_premium (Decimal): The starting base premium
        ws_monthly_premium (Decimal): The monthly premium amount
        ws_annual_premium (Decimal): The annual premium amount
    Returns:
        tuple[Decimal, Decimal]: A tuple containing the calculated monthly premium and annual premium
    Raises:
        ValueError: If any input values are invalid
    Example:
        >>> calc_health_premium_C8(25, 'SILVER', 'N', Decimal('0'), Decimal('0'), Decimal('0'))
        (Decimal('300.00'), Decimal('3600.00'))
    """
    logger.info("Starting calc_health_premium_C8")

    # Input validation
    if not isinstance(ws_insured_age, int):
        logger.error(f"Invalid insured age: {ws_insured_age}")
        raise ValueError("Insured age must be an integer.")
    if not isinstance(ws_plan_type, str) or ws_plan_type not in ('BRONZE', 'SILVER', 'GOLD', 'PLATINUM'):
        logger.error(f"Invalid plan type: {ws_plan_type}")
        raise ValueError("Plan type must be 'BRONZE', 'SILVER', 'GOLD', or 'PLATINUM'.")
    if not isinstance(ws_family_plan, str) or ws_family_plan not in ('Y', 'N'):
        logger.error(f"Invalid family plan indicator: {ws_family_plan}")
        raise ValueError("Family plan must be 'Y' or 'N'.")

    try:
        # Initialize base premium
        ws_base_premium = Decimal('300')
        logger.debug(f"Initial base premium: {ws_base_premium}")

        # Evaluate insured age and adjust base premium
        if 0 <= ws_insured_age <= 18:
            ws_base_premium *= Decimal('0.5')
            logger.debug("Insured age adjusted base premium by 0.5")
        elif 19 <= ws_insured_age <= 30:
            ws_base_premium *= Decimal('1.0')
            logger.debug("Insured age adjusted base premium by 1.0")
        elif 31 <= ws_insured_age <= 40:
            ws_base_premium *= Decimal('1.3')
            logger.debug("Insured age adjusted base premium by 1.3")
        elif 41 <= ws_insured_age <= 50:
            ws_base_premium *= Decimal('1.6')
            logger.debug("Insured age adjusted base premium by 1.6")
        elif 51 <= ws_insured_age <= 60:
            ws_base_premium *= Decimal('2.0')
            logger.debug("Insured age adjusted base premium by 2.0")
        else:
            ws_base_premium *= Decimal('2.8')
            logger.debug("Insured age adjusted base premium by 2.8")

        # Evaluate plan type and adjust base premium
        if ws_plan_type == 'BRONZE':
            ws_base_premium *= Decimal('0.8')
            logger.debug("Plan type adjusted base premium by 0.8")
        elif ws_plan_type == 'SILVER':
            ws_base_premium *= Decimal('1.0')
            logger.debug("Plan type adjusted base premium by 1.0")
        elif ws_plan_type == 'GOLD':
            ws_base_premium *= Decimal('1.3')
            logger.debug("Plan type adjusted base premium by 1.3")
        elif ws_plan_type == 'PLATINUM':
            ws_base_premium *= Decimal('1.6')
            logger.debug("Plan type adjusted base premium by 1.6")

        # Adjust premium for family plan
        if ws_family_plan == 'Y':
            ws_base_premium *= Decimal('2.5')
            logger.debug("Family plan adjusted base premium by 2.5")

        # Move base premium to monthly premium
        ws_monthly_premium = ws_base_premium
        ws_monthly_premium = ws_monthly_premium.quantize(Decimal('0.01'))

        # Calculate annual premium
        ws_annual_premium = ws_monthly_premium * Decimal('12')
        ws_annual_premium = ws_annual_premium.quantize(Decimal('0.01'))

        logger.info("Completed calc_health_premium_C8 successfully")
        return ws_monthly_premium, ws_annual_premium

    except Exception as e:
        logger.error(f"Error in calc_health_premium_C8: {e}")
        raise

