    try:
        global ws_risk_points, policy_life, policy_auto, ws_bmi, ws_smoker_flag, ws_hazardous_occupation, ws_driver_age, ws_accidents_3yr

        ws_risk_points = 0
        logger.debug(f"Initial ws_risk_points set to: {ws_risk_points}")

        if policy_life:
            if ws_bmi > 30:
                ws_risk_points += 10
                logger.debug(f"BMI risk factor added 10 points, ws_risk_points is now: {ws_risk_points}")
            if ws_smoker_flag == 'Y':
                ws_risk_points += 25
                logger.debug(f"Smoker risk factor added 25 points, ws_risk_points is now: {ws_risk_points}")
            if ws_hazardous_occupation == 'Y':
                ws_risk_points += 15
                logger.debug(f"Hazardous occupation risk factor added 15 points, ws_risk_points is now: {ws_risk_points}")

        if policy_auto:
            if ws_driver_age < 21:
                ws_risk_points += 20
                logger.debug(f"Driver age risk factor added 20 points, ws_risk_points is now: {ws_risk_points}")
            if ws_accidents_3yr > 1:
                ws_risk_points += 15
                logger.debug(f"Accidents risk factor added 15 points, ws_risk_points is now: {ws_risk_points}")
        logger.info("Completed evaluate_risk_factors_C8 successfully")

    except Exception as e:
        logger.error(f"Error in evaluate_risk_factors_C8: {e}")
        raise

