def calculate_match_score_C9(
    ws_ofac_score: int,
    ws_pep_score: int,
    ws_watchlist_hits: int
) -> Decimal:
    """
    Calculates the match score based on OFAC score, PEP score, and watchlist hits
    This function adds the OFAC score and PEP score to ws_match_score, and then divides
    ws_match_score by ws_watchlist_hits to calculate the final match score
    Args:
        ws_ofac_score: The OFAC score
        ws_pep_score: The PEP score
        ws_watchlist_hits: The number of watchlist hits
    Returns:
        Decimal: The calculated match score, rounded to two decimal places. Returns 0 if ws_watchlist_hits is zero
    Raises:
        ValueError: If any of the input scores are not integers or ws_watchlist_hits is not an integer
        ZeroDivisionError: If ws_watchlist_hits is zero
    Example:
        calculate_match_score_C9(50, 25, 3)
    """
    logger.info("Calculating match score")

    # Input Validation
    if not isinstance(ws_ofac_score, int):
        logger.error(f"Invalid ws_ofac_score type: {type(ws_ofac_score)}")
        raise ValueError("ws_ofac_score must be an integer.")

    if not isinstance(ws_pep_score, int):
        logger.error(f"Invalid ws_pep_score type: {type(ws_pep_score)}")
        raise ValueError("ws_pep_score must be an integer.")

    if not isinstance(ws_watchlist_hits, int):
        logger.error(f"Invalid ws_watchlist_hits type: {type(ws_watchlist_hits)}")
        raise ValueError("ws_watchlist_hits must be an integer.")

    try:
        ws_match_score = 0
        if ws_ofac_score > 0:
            ws_match_score += ws_ofac_score
            logger.debug(f"Added OFAC score, match score now {ws_match_score}")

        if ws_pep_score > 0:
            ws_match_score += ws_pep_score
            logger.debug(f"Added PEP score, match score now {ws_match_score}")

        if ws_watchlist_hits > 0:
            ws_match_score = Decimal(str(ws_match_score)) / Decimal(str(ws_watchlist_hits))
            ws_match_score = ws_match_score.quantize(Decimal("0.01"))
            logger.debug(f"Match score divided by watchlist hits: {ws_match_score}")
        else:
            logger.warning("Watchlist hits is zero, returning match score of 0.")
            return Decimal("0.00")

        logger.info(f"Final match score calculated: {ws_match_score}")
        return ws_match_score
    except ZeroDivisionError as zde:
        logger.error(f"Division by zero error: {zde}")
        raise
    except Exception as e:
        logger.error(f"Error calculating match score: {e}")
        raise

def determine_disposition_C9(
    ws_match_score: Decimal
) -> Dict[str,str]:
    """
    Determines the disposition based on the match score
    This function sets the ws_match_type and ws_case_status based on the value of ws_match_score
    Args:
        ws_match_score: The match score (Decimal)
    Returns:
        Dict[str,str]: A dictionary containing the determined match type and case status
    Raises:
        ValueError: If ws_match_score is not a Decimal
    Example:
        determine_disposition_C9(Decimal('85.00'))
    """
    logger.info("Determining disposition")

    # Input Validation
    if not isinstance(ws_match_score, Decimal):
        logger.error(f"Invalid ws_match_score type: {type(ws_match_score)}")
        raise ValueError("ws_match_score must be a Decimal.")

    try:
        ws_match_type = ""
        ws_sar_required = ""
        ws_case_status = ""

        if ws_match_score >= Decimal('90'):
            ws_match_type = 'CONFIRMED'
            ws_sar_required = 'Y'
            logger.debug(f"Match score >= 90, type is CONFIRMED, SAR required is Y")

        elif ws_match_score >= Decimal('75'):
            ws_match_type = 'POTENTIAL'
            ws_case_status = 'REVIEW'
            logger.debug(f"Match score >= 75, type is POTENTIAL, case status is REVIEW")

        elif ws_match_score >= Decimal('50'):
            ws_match_type = 'WEAK'
            ws_case_status = 'CLEARED'
            logger.debug(f"Match score >= 50, type is WEAK, case status is CLEARED")

        else:
            ws_match_type = 'FALSE POSITIVE'
            ws_case_status = 'CLEARED'
            logger.debug(f"Match score < 50, type is FALSE POSITIVE, case status is CLEARED")
        
        logger.info(f"Match type set to: {ws_match_type}, Case Status set to: {ws_case_status}, SAR required: {ws_sar_required}")
        return {"match_type": ws_match_type, "case_status": ws_case_status, "sar_required": ws_sar_required}

    except Exception as e:
        logger.error(f"Error determining disposition: {e}")
        raise

