        # PERFORM UNTIL ws_eof_flag = 'Y'
        with open(ach_input_file_path, 'r') as f:
            # Skip the header record
            next(f)
            for line in f:
                # READ ach_input_file INTO ws_ach_entry
                ws_ach_entry = line.strip()

                # Check for end of file
                if not ws_ach_entry:
                    # MOVE 'Y' TO ws_eof_flag
                    ws_eof_flag = 'Y'
                    break
                else:
                    # PERFORM 25210-validate_single_entry
                    validate_single_entry_C11()

        # MOVE 'N' TO ws_eof_flag
