def check_availability_C12(
    box_status: List[str],
    box_size: List[str],
    ws_total_boxes: int,
    ws_requested_size: str
) -> Dict[str, Union[str, int]]:
  logger.info("Checking box availability")
  ws_box_available = 'N'
  ws_assigned_box = 0

  try:
      for ws_box_idx in range(1, ws_total_boxes + 1):
          if box_status[ws_box_idx - 1] == 'A':
              if box_size[ws_box_idx - 1] == ws_requested_size:
                  ws_box_available = 'Y'
                  ws_assigned_box = ws_box_idx
                  break

      return {'ws_box_available': ws_box_available, 'ws_assigned_box': ws_assigned_box}
  except Exception as e:
      logger.error(f"Error checking box availability: {e}")
      raise

