def reconcile_difference_C15(
    ws_gl_control_bal: Decimal,
    ws_subledger_total: Decimal,
    ws_recon_diff: Decimal,
) -> None:
    """
    Calculates the reconciliation difference and logs an exception if it's not zero.'

    This function calculates the difference between the general ledger control balance
    and the subledger total. If the reconciliation difference is not zero, it calls
    a separate function to log the reconciliation exception
    Args:
        ws_gl_control_bal: General ledger control balance
        ws_subledger_total: Subledger total
        ws_recon_diff: Reconciliation difference (input/output)
    Returns:
        None

    Raises:
        ValueError: If any of the input values are invalid
    Example:
        >>> reconcile_difference(Decimal('1000.00'), Decimal('999.00'), Decimal('1.00'))
    """
    logger.info("Starting reconcile_difference_C15")

    try:
        # Calculate the reconciliation difference
        recon_diff = ws_gl_control_bal - ws_subledger_total
        logger.debug(f"Reconciliation difference calculated: {recon_diff}")

        #Check if the reconciliation difference is not equal to zero
        if ws_recon_diff != Decimal('0'):
            #Log a reconciliation exception
            log_recon_exception_37235_C15(ws_gl_account = 'SOME_ACCOUNT', ws_recon_diff = recon_diff)
            logger.debug("Reconciliation exception logged.")
        else:
            logger.debug("Reconciliation difference is zero, no exception logged.")

    except Exception as e:
        logger.error(f"Error in reconcile_difference_C15: {e}")
        raise

